  async function changeMessage(req,remove){return transaction(async c=>{const conv=await member(c,req.params.id,req.user.id,{lock:true,...(!remove?{write:true}:{})});const row=(await c.query('SELECT * FROM chat_messages WHERE id=$1 AND conversation_id=$2 FOR UPDATE',[req.params.messageId,req.params.id])).rows[0];if(!row)throw fail(404,'Сообщение не найдено');if(row.sender_id!==req.user.id&&!(remove&&conv.kind==='group'&&['owner','admin'].includes(conv.member.role)))throw fail(403,'Можно изменить только своё сообщение');if(row.system)throw fail(403,'Служебное событие нельзя изменить');if(!remove&&row.deleted_at)throw fail(422,'Сообщение удалено');if(remove)await c.query("UPDATE chat_messages SET deleted_at=coalesce(deleted_at,now()),text='',location=NULL,listing_id=NULL,reply_to_message_id=NULL WHERE id=$1",[row.id]);else{fields(req.body,['text']);const value=text(req.body.text,4000,row.kind==='text');await c.query('UPDATE chat_messages SET text=$2,edited_at=now() WHERE id=$1',[row.id,value]);}const updated=(await c.query('SELECT * FROM chat_messages WHERE id=$1',[row.id])).rows[0];await notify(c,req.params.id,remove?'deleted':'edited',null,remove?{messageId:row.id,deletedAt:iso(updated.deleted_at)}:{});return(await messages(c,[updated],req.user.id))[0];});}
