  async function acknowledge(req,kind){
    fields(req.body,['sequence']);const sequence=req.body.sequence;
    if(!Number.isSafeInteger(sequence)||sequence<0)throw fail(400,'Некорректный номер сообщения');
    return transaction(async c=>{
      const cv=await member(c,req.params.id,req.user.id,{lock:true});
      if(sequence&&!(await c.query('SELECT 1 FROM chat_messages WHERE conversation_id=$1 AND sequence=$2',[req.params.id,sequence])).rowCount)throw fail(422,'Сообщение не найдено');
      const column=kind==='read'?'last_read_sequence':'last_delivered_sequence';
      const row=(await c.query(`UPDATE chat_conversation_members SET ${column}=greatest(${column},$3) WHERE conversation_id=$1 AND user_id=$2 RETURNING *`,[req.params.id,req.user.id,sequence])).rows[0];
      // Keep the old read-cursor store compatible with the previous deployment slot.
      if(kind==='read')await c.query('INSERT INTO chat_message_receipts(conversation_id,user_id,sequence) VALUES($1,$2,$3) ON CONFLICT(conversation_id,user_id) DO UPDATE SET sequence=greatest(chat_message_receipts.sequence,excluded.sequence),read_at=CASE WHEN chat_message_receipts.sequence<excluded.sequence THEN now() ELSE chat_message_receipts.read_at END',[req.params.id,req.user.id,row.last_read_sequence]);
      const stamp=(await c.query('SELECT receipt_version,clock_timestamp() server_at FROM chat_conversations WHERE id=$1',[req.params.id])).rows[0];
      const result={ok:true,conversationId:req.params.id,sequence:Number(row[column]),deliveredSequence:Number(row.last_delivered_sequence),readSequence:Number(row.last_read_sequence),version:Number(stamp.receipt_version),serverAt:iso(stamp.server_at)};
      const privateRead=kind==='read'&&(await c.query('SELECT share_read_receipts FROM chat_privacy WHERE user_id=$1',[req.user.id])).rows[0]?.share_read_receipts===false;
      if(Number(row[column])>Number(cv.member[column])&&(!privateRead||Number(row.last_delivered_sequence)>Number(cv.member.last_delivered_sequence)))await notify(c,req.params.id,privateRead?'delivered':kind,null,{userId:req.user.id,sequence:result.sequence,version:result.version,serverAt:result.serverAt});
      return result;
    });
  }
