  router.get('/attachments/:id/file',wrap(async(req,res)=>{
    const permitted = async () => {
      const a=(await pool.query('SELECT a.*,m.deleted_at FROM chat_attachments a LEFT JOIN chat_messages m ON m.id=a.message_id WHERE a.id=$1',[req.params.id])).rows[0];
      if(!a||a.deleted_at||a.message_id&&(await pool.query('SELECT 1 FROM chat_message_personal WHERE message_id=$1 AND user_id=$2 AND hidden',[a.message_id,req.user.id])).rowCount)throw fail(404,'Файл недоступен');
      const avatar=(await pool.query('SELECT g.access FROM chat_groups g JOIN chat_conversations c ON c.id=g.conversation_id WHERE g.avatar_id=$1 AND c.deleted_at IS NULL',[a.id])).rows[0];
      if(!avatar||avatar.access!=='public')await member(pool,a.conversation_id,req.user.id);
      if(!a.message_id&&!avatar&&a.uploader_id!==req.user.id)throw fail(404,'Файл недоступен');
      return a;
    };
    const a=await permitted(),thumbnail=req.query.size==='thumb'&&['image','video','video_note'].includes(a.kind);
    if(thumbnail&&['video','video_note'].includes(a.kind)) {
      try { await store.ensureVideoThumbnail(a.storage_key); }
      catch(error) { if(error.status===429)throw error;throw fail(404,'Предпросмотр недоступен'); }
      // A legacy poster may take time to decode. Do not serve it after a concurrent
      // leave, personal hide or delete-for-all completed during generation.
      await permitted();
    }
    res.set({'Cache-Control':'private, no-store','Content-Type':thumbnail?'image/webp':a.mime_type,'X-Content-Type-Options':'nosniff','Content-Disposition':`${a.kind==='document'?'attachment':'inline'}; filename*=UTF-8''${encodeURIComponent(a.name)}`,'Content-Security-Policy':"default-src 'none'; sandbox"});
    res.sendFile(store.path(a.storage_key,{thumbnail}),error=>{if(error&&!res.headersSent)res.status(404).json({error:'Файл недоступен'});});
  }));
